/* Optional V3 integration. Disabled until the reviewed server proposals are installed. */
(() => {
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const clone=v=>JSON.parse(JSON.stringify(v)),account=()=>window.KizunaAccount?.getSnapshot?.()||{};
 const enabled=()=>window.KIZUNA_CONFIG?.v3Economy===true;
 const empty=()=>({fortune:{enabled:false,model:'relative',cap:null,eligible:{standard:false,thematic:false,event:false,shop:false,nexus:false},levels:Array.from({length:5},()=>({cost:null,bonus:null}))},events:[]});
 let state=null,owner='',epoch=0,quote=null,quoteId='',panel=null,tab=null,record=null,draft=empty(),preview=null,dirty=false,busy=false,selectedEvent=0;
 const cacheKey=()=>`kizuna_v3_draft_${owner}`;
 const percent=n=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:4})+' %';
 const labels={standard:'Kizuna Mix',thematic:'Thématiques',event:'Événementiels',shop:'Éditions payées en Chakra',nexus:'Coffrets Nexus'};
 const status=(text)=>{const n=document.getElementById('kv3AdminStatus');if(n)n.textContent=text;};
 function changed(){dirty=true;preview=null;const p=document.getElementById('kv3Publish');if(p)p.disabled=true;status('Modifications en brouillon · aucun effet sur les joueurs.');}
 function field(label,path,value,type='number',attrs=''){
  if(type==='checkbox')return `<label><input type="checkbox" data-v3-field="${path}" ${value?'checked':''}> ${label}</label>`;
  return `<label>${label}<input type="${type}" data-v3-field="${path}" value="${esc(value??'')}" ${attrs}></label>`;
 }
 function select(label,path,value,options){return `<label>${label}<select data-v3-field="${path}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}
 function renderAdmin(){
  if(!panel)return;const f=draft.fortune,e=draft.events[selectedEvent];
  panel.innerHTML=`<header><span class="knxa-kicker">KIZUNA 3.0 · ÉQUILIBRAGE</span><h2>Préparer les prochaines rencontres.</h2><p>${enabled()?'Brouillon partagé. La publication demande un aperçu validé.':'Brouillon sur cet appareil. Le service 3.0 attend son installation ; aucune publication n’est disponible.'}</p></header><p id="kv3AdminStatus" role="status"></p>
   <section class="kv3-admin-box"><h3>Fortune mythique</h3><p>Les bonus des paliers acquis s’additionnent. Le bonus du booster est appliqué en premier, puis Fortune, puis le plafond. Les garanties restent prioritaires.</p><div class="kv3-fields">${field('Préparer son activation','fortune.enabled',f.enabled,'checkbox')}${select('Type de bonus','fortune.model',f.model,[['relative','Relatif (%)'],['points','Points de pourcentage']])}${field('Plafond de probabilité (%)','fortune.cap',f.cap,'number','min="0" max="100" step="0.001"')}</div><div class="kv3-levels">${f.levels.map((l,i)=>`<fieldset><legend>Fortune ${['I','II','III','IV','V'][i]}</legend>${field('Coût en Chakra',`fortune.levels.${i}.cost`,l.cost,'number','min="0" step="1"')}${field('Bonus supplémentaire',`fortune.levels.${i}.bonus`,l.bonus,'number','min="0" step="0.001"')}</fieldset>`).join('')}</div><fieldset><legend>Booster éligible à Fortune</legend><div class="kv3-fields">${Object.entries(labels).map(([k,v])=>field(v,'fortune.eligible.'+k,f.eligible[k],'checkbox')).join('')}</div></fieldset></section>
   <section class="kv3-admin-box"><h3>Éditions événementielles</h3><div class="kv3-admin-actions">${['Convergence','Éclipse Mythique','Paradoxe','Origines'].map(n=>`<button type="button" data-v3-preset="${n}">+ ${n}</button>`).join('')}</div><p>Chaque édition démarre désactivée. Les cartes sont tirées par le moteur habituel.</p><label>Édition à préparer<select id="kv3EventSelect"><option value="">Choisir une édition</option>${draft.events.map((x,i)=>`<option value="${i}" ${i===selectedEvent?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
   ${e?`<div class="kv3-fields">${field('Nom',`events.${selectedEvent}.name`,e.name,'text','maxlength="60"')}${field('Description',`events.${selectedEvent}.description`,e.description,'text','maxlength="300"')}${field('Illustration (HTTPS ou assets/)',`events.${selectedEvent}.image`,e.image,'text')}${select('Source',`events.${selectedEvent}.source`,e.source,[['stock','Réserve de boosters'],['chakra','Chakra'],['nexus','Réserve de coffrets Nexus']])}${field('Prix par booster en Chakra',`events.${selectedEvent}.price`,e.price,'number','min="0" step="1"')}${field('Début (date ISO avec fuseau)',`events.${selectedEvent}.startsAt`,e.startsAt,'text','placeholder="2027-01-01T00:00:00Z"')}${field('Fin (date ISO avec fuseau)',`events.${selectedEvent}.endsAt`,e.endsAt,'text','placeholder="2027-01-08T00:00:00Z"')}${select('Type de bonus mythique',`events.${selectedEvent}.bonusModel`,e.bonusModel,[['relative','Relatif (%)'],['points','Points de pourcentage']])}${field('Bonus mythique',`events.${selectedEvent}.bonus`,e.bonus,'number','min="0" step="0.001"')}${field('Plafond mythique (%)',`events.${selectedEvent}.cap`,e.cap,'number','min="0" max="100" step="0.001"')}${field('Chance de favoriser une carte manquante (%)',`events.${selectedEvent}.collectionBonus`,e.collectionBonus,'number','min="0" max="100" step="0.01"')}${field('Éligible à Fortune',`events.${selectedEvent}.fortuneEligible`,e.fortuneEligible,'checkbox')}${field('Préparer son activation',`events.${selectedEvent}.enabled`,e.enabled,'checkbox')}</div><fieldset><legend>Rareté minimale par carte</legend><div class="kv3-fields">${e.minLevels.map((v,i)=>select('Carte '+(i+1),`events.${selectedEvent}.minLevels.${i}`,String(v),['Commun','Peu commune','Rare','Épique','Légendaire','Mythique'].map((r,j)=>[String(j+1),r+' ou mieux']).filter((_,j)=>j+1>=[1,1,1,2,3][i]))).join('')}</div></fieldset><p>Les garanties de base ne peuvent pas être réduites. Pity : 50 / 250 paquets. Dates facultatives ; sans date, l’édition est permanente. Le bonus de collection choisit parmi les cartes de la rareté déjà tirée.</p><label>Rechercher des personnages<input type="search" id="kv3PoolSearch" placeholder="Personnage ou anime"></label><p id="kv3PoolCount"></p><div id="kv3Pool" class="kv3-pool"></div>`:''}</section>
   <section class="kv3-admin-box"><h3>Aperçu économique</h3><div id="kv3Comparison">Enregistre puis vérifie le brouillon. Les champs vides ne seront jamais traités comme des prix gratuits.</div></section>
   <div class="kv3-admin-actions"><button type="button" data-v3-admin="save">Enregistrer le brouillon</button><button type="button" data-v3-admin="preview">Vérifier et prévisualiser</button><button type="button" data-v3-admin="export">Exporter le brouillon</button><button type="button" data-v3-admin="publish" id="kv3Publish" disabled>Publier cette configuration</button></div>`;
  renderPool();
 }
 function renderPool(){const host=document.getElementById('kv3Pool'),e=draft.events[selectedEvent];if(!host||!e)return;const q=(document.getElementById('kv3PoolSearch')?.value||'').toLocaleLowerCase('fr');const cards=(window.KizunaGame?.getSnapshot?.().cards||[]).filter(c=>(c.name+' '+c.series).toLocaleLowerCase('fr').includes(q));host.innerHTML=cards.slice(0,60).map(c=>`<label><input type="checkbox" data-v3-card="${esc(c.id)}" ${e.pool.includes(String(c.id))?'checked':''}><span>${esc(c.name)}<small>${esc(c.series)} · ${esc(c.rarity)}</small></span></label>`).join('');document.getElementById('kv3PoolCount').textContent=`${e.pool.length} personnages sélectionnés · ${cards.length} résultats (${Math.min(60,cards.length)} affichés). Affine la recherche pour choisir les autres.`;}
 function localValidation(){const errors=[],f=draft.fortune;if(f.enabled){if(!Number.isFinite(f.cap)||f.cap<=0||f.cap>100)errors.push('Fortune : plafond requis entre 0 et 100 %.');f.levels.forEach((l,i)=>{if(!Number.isSafeInteger(l.cost)||l.cost<0||!Number.isFinite(l.bonus)||l.bonus<0)errors.push(`Fortune ${i+1} : coût et bonus à renseigner.`);});}for(const e of draft.events.filter(e=>e.enabled)){if(!e.image||(e.startsAt&&!Number.isFinite(Date.parse(e.startsAt)))||(e.endsAt&&!Number.isFinite(Date.parse(e.endsAt)))||(e.startsAt&&e.endsAt&&Date.parse(e.endsAt)<=Date.parse(e.startsAt)))errors.push(e.name+' : illustration et dates valides requises.');if(e.pool.length<6)errors.push(e.name+' : sélectionner les six raretés.');if(e.bonus===null||e.cap===null||e.collectionBonus===null||e.source==='chakra'&&e.price===null)errors.push(e.name+' : valeurs économiques à compléter.');}return errors;}
 function previewMarkup(){const f=draft.fortune;return `<p><strong>${f.enabled?'Fortune proposée à l’activation':'Fortune reste inactive'}</strong> · modèle ${f.model==='relative'?'relatif':'en points de pourcentage'} · plafond ${f.cap===null?'non défini':percent(f.cap)}</p><table><thead><tr><th>Palier</th><th>Coût unique</th><th>Bonus ajouté</th></tr></thead><tbody>${f.levels.map((l,i)=>`<tr><td>${i+1}</td><td>${l.cost===null?'À valider':l.cost+' Chakra'}</td><td>${l.bonus===null?'À valider':l.bonus+(f.model==='relative'?' % relatif':' point(s)')}</td></tr>`).join('')}</tbody></table><p>${draft.events.filter(e=>e.enabled).length} édition(s) proposée(s) à l’activation. Les achats existants sont conservés.</p>`;}
 async function adminAction(action){
  if(busy||account().isAdmin!==true)return;const generation=epoch;busy=true;
  try{
   if(action==='export'){const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kizuna-v3-brouillon.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
   if(action==='publish'){
    if(!enabled()||dirty||!preview?.hash)return;
    const dialog=document.createElement('dialog');dialog.className='knx-confirm';dialog.innerHTML='<h2>Publier la configuration ?</h2><p>Les prix et probabilités de ce brouillon s’appliqueront aux prochaines opérations. Les achats passés restent acquis.</p><button type="button" data-cancel>Annuler</button><button type="button" data-confirm>Confirmer la publication</button>';document.body.append(dialog);
    const accepted=await new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='yes'),{once:true});dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]').onclick=()=>dialog.close('yes');dialog.showModal();});dialog.remove();if(!accepted||generation!==epoch)return;
    record=await window.KizunaAccount.v3Request('admin','publish',{revision:record.revision,hash:preview.hash,approved:true});if(generation!==epoch)return;preview=null;dirty=false;status('Configuration publiée.');await refresh();return;
   }
   if(action==='save'){
    if(enabled()){if(!record)record=await window.KizunaAccount.v3Request('admin','get',{});record=await window.KizunaAccount.v3Request('admin','save',{revision:record.revision,config:draft});}
    else localStorage.setItem(cacheKey(),JSON.stringify(draft));
    if(generation!==epoch)return;dirty=false;preview=null;status(enabled()?'Brouillon partagé enregistré.':'Brouillon enregistré sur cet appareil. Rien n’a été publié.');
   }else if(action==='preview'){
    const errors=localValidation();if(errors.length)throw Error(errors.join(' '));
    if(enabled()){if(dirty||!record)throw Error('Enregistre le brouillon avant de demander sa validation serveur.');preview=await window.KizunaAccount.v3Request('admin','preview',{revision:record.revision});}
    if(generation!==epoch)return;document.getElementById('kv3Comparison').innerHTML=previewMarkup();document.getElementById('kv3Publish').disabled=!enabled()||!preview?.hash;status(enabled()?'Aperçu validé par le serveur.':'Aperçu local : la validation serveur et la publication restent désactivées.');
   }
  }catch(error){if(generation===epoch)status(error.publicMessage||error.message||'Impossible d’enregistrer.');}finally{if(generation===epoch)busy=false;}
 }
 function mount(){
  const a=account(),id=a.user?.id||'';
  if(id!==owner){owner=id;epoch++;state=null;quote=null;record=null;preview=null;dirty=false;busy=false;panel?.remove();tab?.remove();panel=tab=null;draft=empty();try{const saved=JSON.parse(localStorage.getItem(cacheKey()));if(saved?.fortune&&Array.isArray(saved.events))draft=saved;}catch{}}
  if(a.isAdmin!==true){panel?.remove();tab?.remove();panel=tab=null;return;}
  const host=document.getElementById('staffPage');if(panel||!host?.querySelector('.ks-tabs'))return;
  tab=document.createElement('button');tab.type='button';tab.textContent='Fortune & éditions';tab.dataset.ksTab='v3';tab.setAttribute('aria-controls','ks-v3');host.querySelector('.ks-tabs').append(tab);
  panel=document.createElement('section');panel.id='ks-v3';panel.className='ks-panel knxa';panel.hidden=true;host.querySelector('.ks-wrap').append(panel);renderAdmin();
  tab.addEventListener('click',async()=>{host.querySelectorAll('.ks-panel').forEach(n=>n.hidden=n!==panel);host.querySelectorAll('.ks-tabs button').forEach(n=>{n.classList.toggle('is-active',n===tab);n.setAttribute('aria-pressed',String(n===tab));});if(enabled()&&!record){const gen=epoch;try{const next=await window.KizunaAccount.v3Request('admin','get',{});if(gen!==epoch)return;record=next;draft=clone(next.draft);renderAdmin();}catch(e){status(e.message);}}});
  panel.addEventListener('input',e=>{if(e.target.id==='kv3PoolSearch'){renderPool();return;}const path=e.target.dataset.v3Field;if(!path)return;const keys=path.split('.'),last=keys.pop();let obj=draft;for(const k of keys)obj=obj[k];obj[last]=e.target.type==='checkbox'?e.target.checked:(e.target.type==='number'||path.includes('.minLevels.'))?(e.target.value===''?null:Number(e.target.value)):e.target.value===''&&/\.(startsAt|endsAt)$/.test(path)?null:e.target.value;changed();});
  panel.addEventListener('change',e=>{if(e.target.id==='kv3EventSelect'){selectedEvent=Number(e.target.value);renderAdmin();}if(e.target.dataset.v3Card){const id=e.target.dataset.v3Card,edition=draft.events[selectedEvent];edition.pool=e.target.checked?[...new Set([...edition.pool,id])]:edition.pool.filter(x=>x!==id);changed();renderPool();}});
  panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.v3Admin)adminAction(b.dataset.v3Admin);if(b.dataset.v3Preset){draft.events.push({id:crypto.randomUUID(),name:b.dataset.v3Preset,description:'',image:'',pool:[],source:'stock',price:null,startsAt:null,endsAt:null,bonusModel:'relative',bonus:null,cap:null,fortuneEligible:false,collectionBonus:null,minLevels:[1,1,1,2,3],enabled:false});selectedEvent=draft.events.length-1;changed();renderAdmin();}});
 }
 async function refresh(){if(!enabled())return;const generation=epoch;try{const next=await window.KizunaAccount.v3Request('read','state',{});if(generation!==epoch)return;state=next;window.dispatchEvent(new CustomEvent('kizuna:v3-change'));}catch{state=null;}}
 async function getQuote(booster){quote=null;quoteId='';if(!enabled()||!account().user)throw Error('Connexion requise.');const generation=epoch,id=account().user.id;const result=await window.KizunaAccount.v3Request('read','quote',{booster});if(generation!==epoch||account().user?.id!==id)throw Error('Le compte connecté a changé.');quote=result;quoteId=booster;return clone(result);}
 function event(booster){return state?.events?.find(e=>'staff:'+e.id===booster);}
 function available(booster,snapshot){const e=event(booster);if(!e)return null;if(!enabled()||!account().user||!e.enabled||Date.now()<Date.parse(e.startsAt)||Date.now()>=Date.parse(e.endsAt))return 0;return e.source==='chakra'?e.price===0?10:Math.floor(snapshot.chakra/e.price):e.source==='nexus'?Number(snapshot.stock.nexusWeekly)||0:null;}
 function quoteStamp(booster){if(!enabled()||!quote||quoteId!==booster)return {};return {quoteVersion:quote.version,expectedPity:quote.pity};}
 function fortuneMarkup(){
  const f=state?.fortune,active=enabled()&&state?.engineReady&&f?.enabled,rank=Number(state?.tier)||0,balance=window.KizunaGame?.getSnapshot?.().chakra||0;
  if(!active)return '<div class="kv3-fortune-info"><span class="knx-eyebrow">FORTUNE · EN PRÉPARATION</span><h2>Chaque rencontre a sa chance.</h2><p>Les cinq paliers attendent la validation de leurs coûts et bonus. Aucun bonus Fortune n’est actif.</p><ol>'+['I','II','III','IV','V'].map(t=>'<li>Fortune '+t+' · valeurs à valider</li>').join('')+'</ol><button type="button" disabled>Pas encore disponible</button><p>La voie Destin et ses suivis restent disponibles.</p></div>';
  return '<div class="kv3-fortune-info"><span class="knx-eyebrow">FORTUNE · '+rank+' / 5</span><h2>La chance se cultive.</h2><p>Bonus '+(f.model==='relative'?'relatifs':'en points de pourcentage')+' cumulatifs, après le bonus du booster. Plafond : '+percent(f.cap)+'.</p><ol>'+f.levels.map((l,i)=>'<li><strong>Fortune '+(i+1)+'</strong> · +'+l.bonus+(f.model==='relative'?' % relatif':' point(s)')+'<br>'+l.cost+' Chakra · '+(i<rank?'Acquis':i>rank?'Palier précédent requis':!account().user?'Connexion requise':balance<l.cost?'Chakra insuffisant':'Disponible')+'</li>').join('')+'</ol><button type="button" data-v3-buy-fortune '+(rank>=5||!account().user||balance<f.levels[rank]?.cost?'disabled':'')+'>'+(rank>=5?'Voie au maximum':'Débloquer Fortune '+(rank+1))+'</button><p>Éligible : '+Object.entries(labels).filter(([k])=>f.eligible[k]).map(([,v])=>v).join(', ')+'.</p></div>';
 }
 async function buyFortune(){
  if(busy||!enabled()||!state?.engineReady||!state.fortune?.enabled||!account().user)return;
  const rank=Number(state.tier)||0,item=state.fortune.levels[rank],generation=epoch;if(!item||item.cost===null)return;
  const payload={tier:rank+1,expectedCost:item.cost,version:state.version};busy=true;
  const dialog=document.createElement('dialog');dialog.className='knx-confirm';dialog.innerHTML='<h2>Débloquer Fortune '+(rank+1)+' ?</h2><p>Coût unique : '+item.cost+' Chakra. Le bonus s’applique uniquement aux boosters éligibles.</p><button type="button" data-cancel>Annuler</button><button type="button" data-confirm>Confirmer l’achat</button>';document.body.append(dialog);
  try{const accepted=await new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='yes'),{once:true});dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]').onclick=()=>dialog.close('yes');dialog.showModal();});if(!accepted||generation!==epoch)return;await window.KizunaAccount.economyRequest('fortune_buy',payload);if(generation===epoch)await refresh();}catch(error){window.KizunaGame?.notify?.(error.publicMessage||error.message);}finally{dialog.remove();if(generation===epoch)busy=false;}
 }
 document.addEventListener('click',e=>{if(e.target.closest('[data-v3-buy-fortune]'))buyFortune();});
 window.KizunaV3={getSnapshot:()=>state?clone(state):null,getQuote,quoteStamp,available,event,refresh,fortuneMarkup};
 document.addEventListener('kizuna:account-change',()=>{mount();refresh();});window.addEventListener('kizuna:economy-change',refresh);
 if(document.querySelector('main'))new MutationObserver(mount).observe(document.querySelector('main'),{childList:true,subtree:true});mount();refresh();
})();
